'use client';

import { type ReactNode, useEffect, useMemo, useRef } from 'react';
import { twMerge } from 'tailwind-merge';

export type ImageTrailVariant = 'follow' | 'momentum' | 'bounce';

export type ImageTrailEffect = {
  keyframes: (sample: {
    delta: Point;
    position: Point;
    width: number;
    height: number;
    speed: number;
    index: number;
  }) => Keyframe[];
  anchor?: 'center';
  persist?: boolean;
};

export interface ImageMouseTrailProps {
  items: string[];
  children?: ReactNode;
  className?: string;
  imgClass?: string;
  /** Legacy density control. Higher values emit more images. */
  distance?: number;
  /** Distance in local CSS pixels between images. Overrides distance. */
  threshold?: number;
  /** Minimum milliseconds between stamps. A positive value stamps only at the pointer. */
  minInterval?: number;
  maxNumberOfImages?: number;
  fadeAnimation?: boolean;
  variant?: ImageTrailVariant;
  effect?: ImageTrailEffect;
  /** Lifetime in milliseconds for fading trails. */
  duration?: number;
  /** pan-y preserves vertical page scrolling; none enables unrestricted dragging. */
  touchAction?: 'auto' | 'pan-y' | 'none';
}

type Point = { x: number; y: number };
const finite = (value: number, fallback: number) => (Number.isFinite(value) ? value : fallback);

export default function ImageMouseTrail({
  items,
  children,
  className,
  imgClass = 'w-40 h-48',
  distance = 20,
  threshold,
  minInterval = 0,
  maxNumberOfImages = 5,
  fadeAnimation = false,
  variant = 'follow',
  effect,
  duration = 1200,
  touchAction = 'pan-y',
}: ImageMouseTrailProps) {
  // Equal URL lists should not restart the trail when a parent re-renders.
  const sourceKey = JSON.stringify(items);
  const sources = useMemo<string[]>(() => JSON.parse(sourceKey), [sourceKey]);
  const containerRef = useRef<HTMLDivElement>(null);
  const layerRef = useRef<HTMLDivElement>(null);
  const poolSize = items.length
    ? Math.min(30, Math.max(1, Math.floor(finite(maxNumberOfImages, 5))))
    : 0;

  useEffect(() => {
    const container = containerRef.current;
    const layer = layerRef.current;
    if (!container || !layer || !poolSize) return;
    const images = Array.from(layer.querySelectorAll('img'));
    const animations = new Map<HTMLImageElement, Animation>();
    const ready = new Set<string>();
    let disposed = false;
    // Warm the browser cache without blocking the page behind a loader.
    const preload = [...new Set(sources)].map((src) => {
      const image = new Image();
      image.onload = () => {
        if (disposed) return;
        ready.add(src);
        if (pending && !frame) frame = requestAnimationFrame(render);
      };
      image.src = src;
      if (image.complete && image.naturalWidth > 0) ready.add(src);
      return image;
    });
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
    let frame = 0;
    let pending: Point | null = null;
    let last: Point | null = null;
    let lastEmission = -Infinity;
    let index = 0;
    let sequence = 0;
    let order: HTMLImageElement[] = [];
    let lastMove: (Point & { time: number }) | null = null;
    let speed = 0;
    const fading = effect ? !effect.persist : fadeAnimation || variant !== 'follow';
    const lifetime = Math.max(400, finite(duration, 1200));
    const interval = Math.max(0, finite(minInterval, 0));

    const clear = () => {
      cancelAnimationFrame(frame);
      frame = 0;
      pending = last = lastMove = null;
      lastEmission = -Infinity;
      speed = 0;
      animations.forEach((animation) => animation.cancel());
      animations.clear();
      images.forEach((image) => {
        image.style.opacity = '0';
      });
      order = [];
    };

    const emit = (at: Point, delta: Point) => {
      const available = sources.filter((src) => ready.has(src));
      if (!available.length) return false;
      const image = images[index++ % images.length];
      animations.get(image)?.cancel();
      image.src = available[sequence++ % available.length];
      const width = container.clientWidth;
      const height = container.clientHeight;
      image.style.left = `${effect?.anchor === 'center' ? width / 2 : at.x}px`;
      image.style.top = `${effect?.anchor === 'center' ? height / 2 : at.y}px`;
      // Rebase a bounded stack instead of wrapping z-index underneath older images.
      order = order.filter((item) => item !== image);
      order.push(image);
      order.forEach((item, i) => {
        item.style.zIndex = String(i + 1);
      });
      const transform = (x = 0, y = 0, scale = 1, rotation = 0) =>
        `translate(-50%, -50%) translate(${x}px, ${y}px) rotate(${rotation}deg) scale(${scale})`;
      const dx = Math.max(-100, Math.min(100, delta.x));
      const dy = Math.max(-100, Math.min(100, delta.y));
      let keyframes: Keyframe[];
      if (reducedMotion.matches) {
        keyframes = [
          { opacity: 0, transform: transform() },
          { opacity: 1, transform: transform(), offset: 0.2 },
          { opacity: fading ? 0 : 1, transform: transform() },
        ];
      } else if (effect) {
        keyframes = effect.keyframes({
          delta: { x: dx, y: dy },
          position: at,
          width,
          height,
          speed,
          index,
        });
      } else if (variant === 'bounce') {
        keyframes = [
          { opacity: 0, transform: transform(0, 0, 0.15), offset: 0 },
          { opacity: 1, transform: transform(0, 0, 1.14), offset: 0.18 },
          { opacity: 1, transform: transform(0, 0, 0.94), offset: 0.28 },
          { opacity: 1, transform: transform(), offset: 0.38 },
          { opacity: 1, transform: transform(), offset: 0.65 },
          { opacity: 1, transform: transform(0, 0, 1.12), offset: 0.76 },
          { opacity: 0, transform: transform(0, 0, 0), offset: 1 },
        ];
      } else if (variant === 'momentum') {
        const angle = dx * 0.12;
        keyframes = [
          { opacity: 0, transform: transform(-dx * 0.35, -dy * 0.35, 0.75, -angle), offset: 0 },
          { opacity: 1, transform: transform(0, 0, 1, angle), offset: 0.2 },
          { opacity: 1, transform: transform(dx * 0.5, dy * 0.5, 1, angle), offset: 0.55 },
          { opacity: 0, transform: transform(dx, dy + 35, 0.85, angle * 1.8), offset: 1 },
        ];
      } else {
        keyframes = [
          { opacity: 0, transform: transform(-dx * 0.5, -dy * 0.5, 0.8), offset: 0 },
          { opacity: 1, transform: transform(), offset: 0.25 },
          { opacity: 1, transform: transform(), offset: 0.6 },
          { opacity: fading ? 0 : 1, transform: transform(0, 0, fading ? 0.85 : 1), offset: 1 },
        ];
      }
      // Ease each segment without compressing the hold and rebound phases.
      for (const keyframe of keyframes) {
        keyframe.easing ??= 'cubic-bezier(0.22, 1, 0.36, 1)';
      }
      const animation = image.animate(keyframes, {
        duration: lifetime,
        fill: 'forwards',
      });
      animations.set(image, animation);
      if (fading)
        animation.onfinish = () => {
          if (animations.get(image) !== animation) return;
          image.style.opacity = '0';
          animation.cancel();
          animations.delete(image);
          order = order.filter((item) => item !== image);
        };
      return true;
    };

    const render = (time: number) => {
      frame = 0;
      if (!pending) return;
      const target = pending;
      pending = null;
      if (time - lastEmission < interval) return;
      const start = last ?? target;
      const dx = target.x - start.x;
      const dy = target.y - start.y;
      const length = Math.hypot(dx, dy);
      const spacing = Math.max(
        8,
        finite(threshold ?? container.clientWidth / Math.max(1, finite(distance, 20)), 40)
      );
      if (!last || interval > 0) {
        if (last && length < spacing) return;
        if (emit(target, { x: dx, y: dy })) {
          last = target;
          lastEmission = time;
        } else pending = target;
        return;
      }
      // Fill gaps along fast movements, but bound work after a large pointer jump.
      const steps = Math.min(poolSize, Math.floor(length / spacing));
      for (let i = 1; i <= steps; i++) {
        const fraction = steps === poolSize ? i / steps : (i * spacing) / length;
        const point = { x: start.x + dx * fraction, y: start.y + dy * fraction };
        if (emit(point, { x: dx / Math.max(1, steps), y: dy / Math.max(1, steps) })) last = point;
        else {
          pending = target;
          break;
        }
      }
    };
    const move = (event: PointerEvent) => {
      if (!event.isPrimary || (event.pointerType === 'touch' && !event.buttons)) return;
      const rect = container.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      const x = ((event.clientX - rect.left) * container.clientWidth) / rect.width;
      const y = ((event.clientY - rect.top) * container.clientHeight) / rect.height;
      if (x < 0 || y < 0 || x > container.clientWidth || y > container.clientHeight) {
        leave(event);
        return;
      }
      if (effect && lastMove) {
        const elapsed = Math.max(1, event.timeStamp - lastMove.time);
        speed = Math.min(4, Math.hypot(x - lastMove.x, y - lastMove.y) / elapsed);
      }
      lastMove = { x, y, time: event.timeStamp };
      pending = { x, y };
      if (!frame) frame = requestAnimationFrame(render);
    };
    const end = (event: PointerEvent) => {
      if (event.isPrimary) clear();
    };
    const leave = (event: PointerEvent) => {
      if (!event.isPrimary) return;
      cancelAnimationFrame(frame);
      frame = 0;
      pending = last = lastMove = null;
      speed = 0;
      // Let an in-flight bounce/fade complete its exit after the pointer leaves.
      if (!fading && !effect) clear();
    };
    container.addEventListener('pointermove', move, { passive: true });
    container.addEventListener('pointerleave', leave);
    container.addEventListener('pointercancel', end);
    container.addEventListener('pointerup', end);
    window.addEventListener('blur', clear);
    window.addEventListener('resize', clear);
    reducedMotion.addEventListener('change', clear);
    return () => {
      disposed = true;
      clear();
      preload.forEach((image) => {
        image.onload = null;
      });
      container.removeEventListener('pointermove', move);
      container.removeEventListener('pointerleave', leave);
      container.removeEventListener('pointercancel', end);
      container.removeEventListener('pointerup', end);
      window.removeEventListener('blur', clear);
      window.removeEventListener('resize', clear);
      reducedMotion.removeEventListener('change', clear);
    };
  }, [sources, poolSize, distance, threshold, minInterval, fadeAnimation, variant, effect, duration]);

  return (
    <div
      ref={containerRef}
      style={{ touchAction }}
      className={twMerge(
        'relative isolate grid h-[600px] w-full place-items-center overflow-hidden rounded-lg bg-muted text-foreground',
        className
      )}
    >
      <div
        ref={layerRef}
        aria-hidden='true'
        className='pointer-events-none absolute inset-0 z-0 overflow-hidden'
      >
        {Array.from({ length: poolSize }, (_, index) => (
          // Decorative images never capture the pointer or enter the accessibility tree.
          // eslint-disable-next-line @next/next/no-img-element
          <img
            key={index}
            src={items[index % items.length]}
            alt=''
            draggable={false}
            className={twMerge(
              'pointer-events-none absolute left-0 top-0 object-cover opacity-0 will-change-transform',
              imgClass
            )}
          />
        ))}
      </div>
      <div className='relative z-10 w-full'>{children}</div>
    </div>
  );
}

'use client';

import { lazy, Suspense, useId, useMemo, useState } from 'react';
import ImageMouseTrail from '@/components/ui/mousetrail';
import { stampEffects } from './trail-stamp-effects';

const TrailCanvas = lazy(() => import('./trail-canvas'));

type StampPreviewId = Exclude<keyof typeof stampEffects, 'cursor-trailer'>;

type Example = { title: string; description: string } & (
  | { id: 'cursor-trailer'; group: 'codepen' }
  | {
      id: StampPreviewId | 'motion-gooey';
      group: 'image' | 'motion';
      demo: number;
    }
);

const groups = {
  image: 'Image Trail Effects',
  motion: 'Motion Trail Animations',
  codepen: 'CodePen',
};

const examples: Example[] = [
  {
    id: 'image-shrink',
    title: 'Shrink Away',
    description: 'Playful 3D emoji slide to the pointer, then shrink away.',
    group: 'image',
    demo: 1,
  },
  {
    id: 'image-bloom',
    title: 'Bloom Out',
    description: 'Photos grow outward as they dissolve.',
    group: 'image',
    demo: 2,
  },
  {
    id: 'image-fall',
    title: 'Gravity Drop',
    description: 'Photos settle at the pointer and take turns falling out of frame.',
    group: 'image',
    demo: 3,
  },
  {
    id: 'motion-classic',
    title: 'Classic',
    description: 'Photos glide from behind the pointer and shrink as they exit.',
    group: 'motion',
    demo: 1,
  },
  {
    id: 'motion-innerscape',
    title: 'Innerscape',
    description: 'A bright cropped view opens to reveal the full picture.',
    group: 'motion',
    demo: 2,
  },
  {
    id: 'motion-gooey',
    title: 'Gooey',
    description: 'Clay stickers swell into view and connect as they pass each other.',
    group: 'motion',
    demo: 15,
  },
  {
    id: 'cursor-trailer',
    title: 'Cursor Trailer',
    description: 'Move or drag to send clay stickers across the title.',
    group: 'codepen',
  },
];

const photoUrls = (...ids: string[]) =>
  ids.map((id) => `https://images.unsplash.com/photo-${id}?auto=format&fit=crop&w=480&q=80`);

// Fluent Emoji artwork © Microsoft Corporation, MIT licensed.
// https://github.com/microsoft/fluentui-emoji/blob/main/LICENSE
const emojiRoot =
  'https://cdn.jsdelivr.net/gh/microsoft/fluentui-emoji@1ffb34c752ecf5d402f04cfb4b392c77f57c54bc/assets';
const shrinkEmoji = [
  'Melting%20face/3D/melting_face_3d.png',
  'Face%20with%20spiral%20eyes/3D/face_with_spiral_eyes_3d.png',
  'Face%20with%20peeking%20eye/3D/face_with_peeking_eye_3d.png',
  'Star-struck/3D/star-struck_3d.png',
  'Zany%20face/3D/zany_face_3d.png',
  'Sparkling%20heart/3D/sparkling_heart_3d.png',
].map((path) => `${emojiRoot}/${path}`);

type StampPreview = {
  items: string[];
  className: string;
  imgClass?: string;
  duration: number;
  threshold?: number;
  minInterval?: number;
};

const stampPreviews: Record<StampPreviewId, StampPreview> = {
  'image-shrink': {
    items: shrinkEmoji,
    className: 'bg-[#fff1e8] text-[#493029]',
    imgClass: 'size-[clamp(74px,14cqw,122px)] object-contain',
    duration: 1420,
  },
  'image-bloom': {
    items: photoUrls(
      '1795169972131-f816a82536a8',
      '1794350325792-c83741409cc7',
      '1793034574913-b8c21bbd13fb'
    ),
    className: 'bg-[#edf0e3] text-[#293127] bg-[radial-gradient(ellipse_at_28%_0%,#faf9f0,transparent_75%)]',
    duration: 1420,
  },
  'image-fall': {
    items: photoUrls(
      '1793911166330-08fd4bfe75c6',
      '1793033259489-200bd4af74e4',
      '1792081863451-1236a1248831'
    ),
    className: 'bg-[#e6edf3] text-[#25303a] bg-[radial-gradient(ellipse_at_30%_0%,#f7fafc,transparent_74%)]',
    duration: 950,
    threshold: 50,
    minInterval: 195,
  },
  'motion-classic': {
    items: photoUrls(
      '1795258566246-ae94d575fb80',
      '1720462393492-046dfa56b1d1',
      '1792655282510-7c34839d0b2b'
    ),
    className: 'bg-[#202226] text-[#f6f3ed] bg-[repeating-linear-gradient(0deg,transparent_0px,transparent_3px,#ffffff0a_3px,#ffffff0a_4px)]',
    duration: 800,
  },
  'motion-innerscape': {
    items: photoUrls(
      '1635776063043-ab23b4c226f6',
      '1795153624227-49ec391b973e',
      '1788802906864-37fe089b2aff'
    ),
    className: 'bg-[#ddd3ee] text-[#332642] bg-[radial-gradient(ellipse_at_50%_12%,#faf6ff,transparent_74%),repeating-linear-gradient(135deg,transparent_0px,transparent_7px,#31244a14_7px,#31244a14_8px)]',
    duration: 1420,
  },
};

const clayStickers = [
  'alarm-clock',
  'watering-can',
  'fan',
  'mailbox',
  'key',
  'backpack',
  'umbrella',
  'mug',
  'toaster',
  'armchair',
  'flashlight',
  'plant',
];

const trailFonts = `
  @font-face {
    font-family: 'Trail Instrument Serif';
    font-style: normal;
    font-weight: 400;
    font-display: swap;
    src: url('https://fonts.gstatic.com/s/instrumentserif/v5/jizBRFtNs2ka5fXjeivQ4LroWlx-6zUTjg.woff2') format('woff2');
  }
  @font-face {
    font-family: 'Trail Instrument Serif';
    font-style: italic;
    font-weight: 400;
    font-display: swap;
    src: url('https://fonts.gstatic.com/s/instrumentserif/v5/jizHRFtNs2ka5fXjeivQ4LroWlx-6zAjjH7M.woff2') format('woff2');
  }
  @font-face {
    font-family: 'Trail Space Grotesk';
    font-style: normal;
    font-weight: 600;
    font-display: swap;
    src: url('https://fonts.gstatic.com/s/spacegrotesk/v22/V8mQoQDjQSkFtoMM3T6r8E7mF71Q-gOoraIAEj42VnskPMA.woff2') format('woff2');
  }
`;
const displayTitle =
  'pointer-events-none px-4 text-center text-[clamp(2.75rem,8.5cqw,5.5rem)] leading-[0.95] font-normal [font-family:Trail_Instrument_Serif,Georgia,serif]';

const hint = (
  <p className='pointer-events-none text-center text-sm font-medium'>
    Move or drag to reveal the trail
  </p>
);

function ExampleStage({ example, stickers }: { example: Example; stickers: string[] }) {
  if (example.group === 'codepen') {
    return (
      <ImageMouseTrail
        items={stickers}
        effect={stampEffects[example.id]}
        threshold={44}
        maxNumberOfImages={20}
        duration={560}
        touchAction='none'
        imgClass='size-[clamp(72px,12.5cqw,128px)] object-contain'
        className='@container h-[clamp(300px,45vw,430px)] bg-[#fdfdfc] text-[#151510] [&>[aria-hidden=true]]:z-20'
      >
        <h2 className={displayTitle}>
          <em>Beyond the</em> Limit
        </h2>
      </ImageMouseTrail>
    );
  }

  if (example.id !== 'motion-gooey') {
    const { className, imgClass, threshold = 64, ...preview } = stampPreviews[example.id];
    return (
      <ImageMouseTrail
        {...preview}
        effect={stampEffects[example.id]}
        threshold={threshold}
        maxNumberOfImages={11}
        touchAction='none'
        imgClass={imgClass ?? 'h-32 w-24 rounded-sm border border-white/30 shadow-lg sm:h-48 sm:w-36'}
        className={`@container h-[clamp(300px,55vw,520px)] ${className}`}
      >
        {hint}
      </ImageMouseTrail>
    );
  }

  return (
    <div className='@container relative isolate grid h-[clamp(300px,45vw,430px)] touch-none place-items-center overflow-hidden rounded-lg bg-white text-[#151510]'>
      <h2 className='pointer-events-none px-4 text-center text-[clamp(2.5rem,8cqw,5rem)] leading-none font-semibold tracking-[-0.08em] [font-family:Trail_Space_Grotesk,sans-serif]'>
        Soft shapes.
      </h2>
      <TrailCanvas images={stickers} />
    </div>
  );
}

function exampleSource(example: Example) {
  if (example.group === 'codepen') {
    return {
      href: 'https://codepen.io/thingbynemanja/full/ogjaaNE',
      label: 'CodePen by Nemanja Kočović',
    };
  }

  const { group, demo } = example;
  const collection =
    group === 'image' ? 'ImageTrailEffects/blob/master' : 'MotionTrailAnimations/blob/main';
  return {
    href: `https://github.com/codrops/${collection}/index${demo === 1 ? '' : demo}.html`,
    label: `Codrops demo ${demo}`,
  };
}

export function MousetrailExplorerPreview() {
  return <MousetrailExplorer stickerBaseUrl='/image-trail/clay' />;
}

export default function MousetrailExplorer({
  stickerBaseUrl = 'https://www.ui-layouts.com/image-trail/clay',
}: { stickerBaseUrl?: string } = {}) {
  const id = useId();
  const [index, setIndex] = useState(0);
  const stickers = useMemo(() => {
    const baseUrl = stickerBaseUrl.replace(/\/$/, '');
    return clayStickers.map((name) => `${baseUrl}/${name}.webp`);
  }, [stickerBaseUrl]);
  const example = examples[index];
  const source = exampleSource(example);

  function step(amount: number) {
    setIndex((value) => (value + amount + examples.length) % examples.length);
  }

  return (
    <section aria-label='Image trail explorer' className='not-prose grid w-full gap-3'>
      <style>{trailFonts}</style>
      <div className='flex flex-wrap items-end justify-between gap-3'>
        <div className='grid min-w-0 flex-1 gap-1.5'>
          <label htmlFor={id} className='text-sm font-medium'>
            Explore examples
          </label>
          <select
            id={id}
            value={example.id}
            onChange={(event) => {
              const next = examples.findIndex((entry) => entry.id === event.target.value);
              if (next >= 0) setIndex(next);
            }}
            className='h-10 w-full max-w-xs rounded-md border bg-background px-2.5 text-sm text-foreground'
          >
            {(Object.keys(groups) as (keyof typeof groups)[]).map((group) => (
              <optgroup key={group} label={groups[group]}>
                {examples
                  .filter((entry) => entry.group === group)
                  .map((entry) => (
                    <option key={entry.id} value={entry.id}>
                      {entry.title}
                    </option>
                  ))}
              </optgroup>
            ))}
          </select>
        </div>
        <div className='flex shrink-0 items-center gap-2'>
          <button
            type='button'
            aria-label='Previous example'
            onClick={() => step(-1)}
            className='grid size-10 cursor-pointer place-items-center rounded-md border text-lg hover:bg-muted'
          >
            <span aria-hidden='true'>←</span>
          </button>
          <span
            aria-hidden='true'
            className='min-w-12 text-center text-sm tabular-nums text-muted-foreground'
          >
            {index + 1}/{examples.length}
          </span>
          <button
            type='button'
            aria-label='Next example'
            onClick={() => step(1)}
            className='grid size-10 cursor-pointer place-items-center rounded-md border text-lg hover:bg-muted'
          >
            <span aria-hidden='true'>→</span>
          </button>
        </div>
      </div>
      <div data-trail-example={example.id}>
        <Suspense
          fallback={
            <p
              role='status'
              className='grid min-h-80 place-items-center rounded-lg bg-muted text-sm'
            >
              Loading preview…
            </p>
          }
        >
          <ExampleStage key={example.id} example={example} stickers={stickers} />
        </Suspense>
      </div>
      <div className='flex flex-wrap items-baseline justify-between gap-2 text-sm text-muted-foreground'>
        <p aria-live='polite'>
          {example.title}. {example.description}
          {example.id === 'motion-gooey' && ' Canvas adaptation.'}
        </p>
        <a
          href={source.href}
          target='_blank'
          rel='noreferrer'
          className='underline underline-offset-4'
        >
          {source.label}
        </a>
      </div>
    </section>
  );
}

import type { ImageTrailEffect } from '@/components/ui/mousetrail';

type Sample = Parameters<ImageTrailEffect['keyframes']>[0];

const fall = 'cubic-bezier(0.53, 0.02, 0.85, 0.68)';

function frame(
  offset: number,
  opacity = 1,
  x = 0,
  y = 0,
  scale = 1,
  rotation = 0,
  extra: Keyframe = {}
): Keyframe {
  return {
    offset,
    opacity,
    transform: `translate(-50%, -50%) translate(${x}px, ${y}px) rotate(${rotation}deg) scale(${scale})`,
    ...extra,
  };
}

function approach({ delta }: Pick<Sample, 'delta'>, scale = 1, extra?: Keyframe) {
  return frame(0, 1, -delta.x * 0.7, -delta.y * 0.7, scale, 0, extra);
}

export const stampEffects = {
  'cursor-trailer': {
    keyframes: () => {
      const tilt = Math.random() * 40 - 20;
      return [
        frame(0, 1, 0, 0, 0.56, tilt, { easing: 'cubic-bezier(0.16, 1, 0.3, 1)' }),
        frame(0.1, 1, 0, 0, 1.04, tilt),
        frame(0.19, 1, 0, 0, 1, tilt),
        frame(0.53, 1, 0, 0, 1, tilt, { easing: 'cubic-bezier(0.42, 0, 0.78, 0.6)' }),
        frame(1, 0, 0, 0, 0, tilt),
      ];
    },
  },
  'image-shrink': {
    keyframes: (sample) => [approach(sample), frame(0.3), frame(1, 0, 0, 0, 0.2)],
  },
  'image-bloom': {
    keyframes: (sample) => [
      approach(sample),
      frame(0.48),
      frame(1, 0, 0, 0, 2, 0, { filter: 'blur(3px)' }),
    ],
  },
  'image-fall': {
    keyframes: ({ delta, height, position, index }) => [
      approach({ delta }, 0.88),
      frame(0.16),
      // Hold before falling. The demo's minimum stamp interval exceeds this final segment.
      frame(0.8, 1, 0, 0, 1, 0, { easing: fall }),
      frame(1, 1, 0, height - position.y + 120, 0.94, index % 2 ? 12 : -12),
    ],
  },
  'motion-classic': {
    keyframes: (sample) => [
      frame(0, 1, -sample.delta.x, -sample.delta.y),
      frame(0.55, 1, 0, 0, 1, 0, { easing: fall }),
      frame(1, 0, 0, 0, 0.2),
    ],
  },
  'motion-innerscape': {
    keyframes: (sample) => [
      approach(sample, 0.36, { clipPath: 'inset(38% 38%)', filter: 'brightness(2.5)' }),
      frame(0.4, 1, 0, 0, 1, 0, { clipPath: 'inset(0%)', filter: 'brightness(1)' }),
      frame(0.62, 1, 0, 0, 1, 0, { clipPath: 'inset(0%)', filter: 'brightness(1)' }),
      frame(1, 0, 0, 0, 0.2, 0, { clipPath: 'inset(0%)', filter: 'brightness(1)' }),
